import { isEmpty } from "@ember/utils";
import { buildBBCodeAttrs } from "discourse/lib/text";

export default function generateDateMarkup(
  fromDateTime,
  options,
  isRange,
  toDateTime
) {
  const attrs = {};

  if (!isRange) {
    attrs.time = fromDateTime.time;
  }

  attrs.format = fromDateTime.format;
  attrs.timezone = options.timezone;
  attrs.countdown = options.countdown;
  attrs.displayedTimezone = options.displayedTimezone;
  attrs.timezones = Array.isArray(options.timezones)
    ? options.timezones.join("|")
    : options.timezones;

  if (!isRange) {
    attrs.recurring = options.recurring;
  }

  const attrsStr = buildBBCodeAttrs(attrs);
  const suffix = attrsStr ? ` ${attrsStr}` : "";

  if (isRange) {
    const from = [fromDateTime.date, fromDateTime.time]
      .filter((el) => !isEmpty(el))
      .join("T");
    const to = [toDateTime.date, toDateTime.time]
      .filter((el) => !isEmpty(el))
      .join("T");
    return `[date-range from=${from} to=${to}${suffix}]`;
  }

  return `[date=${fromDateTime.date}${suffix}]`;
}
/* eslint-disable ember/no-classic-components, ember/no-observers */
import Component from "@ember/component";
import { fn, hash } from "@ember/helper";
import { on } from "@ember/modifier";
import EmberObject, { action, computed } from "@ember/object";
import { schedule } from "@ember/runloop";
import { trustHTML } from "@ember/template";
import { isEmpty } from "@ember/utils";
import { tagName } from "@ember-decorators/component";
import { observes } from "@ember-decorators/object";
import AdvancedModeToggle from "discourse/components/advanced-mode-toggle";
import { debounce } from "discourse/lib/decorators";
import { INPUT_DELAY } from "discourse/lib/environment";
import { applyLocalDates } from "discourse/lib/local-dates";
import { deepEqual } from "discourse/lib/object";
import { cook } from "discourse/lib/text";
import ComboBox from "discourse/select-kit/components/combo-box";
import MultiSelect from "discourse/select-kit/components/multi-select";
import TimezoneInput from "discourse/select-kit/components/timezone-input";
import DButton from "discourse/ui-kit/d-button";
import DCalendarDateTimeInput from "discourse/ui-kit/d-calendar-date-time-input";
import DModal from "discourse/ui-kit/d-modal";
import DTextField from "discourse/ui-kit/d-text-field";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import generateDateMarkup from "discourse/plugins/discourse-local-dates/lib/local-date-markup-generator";

@tagName("")
export default class LocalDatesCreate extends Component {
  timeFormat = "HH:mm:ss";
  dateFormat = "YYYY-MM-DD";
  dateTimeFormat = "YYYY-MM-DD HH:mm:ss";
  date = null;
  toDate = null;
  time = null;
  toTime = null;
  format = null;
  formats = null;
  recurring = null;
  advancedMode = false;
  timezone = null;
  fromSelected = null;
  toSelected = null;
  countdown = null;
  displayedTimezone = null;

  init() {
    super.init(...arguments);

    this._picker = null;

    this.setProperties({
      timezones: [],
      formats: (this.siteSettings.discourse_local_dates_default_formats || "")
        .split("|")
        .filter((f) => f),
      timezone: this.currentUserTimezone,
      date: moment().format(this.dateFormat),
    });

    const { initialValues } = this.model;

    if (initialValues) {
      this.setProperties(initialValues);
      // open the advanced pane when the date carries an option only editable there
      this.set(
        "advancedMode",
        !!(
          initialValues.format ||
          initialValues.recurring ||
          initialValues.timezones?.length
        )
      );
    }
  }

  get isEditing() {
    return !!this.model.initialValues;
  }

  @computed("date")
  get fromFilled() {
    return !isEmpty(this.date);
  }

  @computed("toDate")
  get toFilled() {
    return !isEmpty(this.toDate);
  }

  @computed("currentUserTimezone", "options.timezone")
  get timezoneIsDifferentFromUserTimezone() {
    return !deepEqual(this.currentUserTimezone, this.options?.timezone);
  }

  @computed("date", "toDate", "toTime")
  get isRange() {
    return this.date && (this.toDate || this.toTime);
  }

  @computed("computedConfig", "isRange")
  get isValid() {
    const fromConfig = this.computedConfig.from;
    if (
      !this.computedConfig.from.dateTime ||
      !this.computedConfig.from.dateTime.isValid()
    ) {
      return false;
    }

    if (this.isRange) {
      const toConfig = this.computedConfig.to;

      if (
        !toConfig.dateTime ||
        !toConfig.dateTime.isValid() ||
        toConfig.dateTime.diff(fromConfig.dateTime) < 0
      ) {
        return false;
      }
    }

    return true;
  }

  @computed("date", "time", "isRange", "options.{format,timezone}")
  get fromConfig() {
    const date = this.date;
    let time = this.time;
    const isRange = this.isRange;
    const options = this.options || {};
    const timeInferred = time ? false : true;

    let dateTime;
    if (!timeInferred) {
      dateTime = moment.tz(`${date} ${time}`, options.timezone);
    } else {
      dateTime = moment.tz(date, options.timezone);
    }

    if (!timeInferred) {
      time = dateTime.format(this.timeFormat);
    }

    let format = options.format;
    if (timeInferred && (format === "LLL" || format === "LLLL")) {
      format = "LL";
    }

    return EmberObject.create({
      date: dateTime.format(this.dateFormat),
      time,
      dateTime,
      format,
      range: isRange ? "start" : false,
    });
  }

  @computed("toDate", "toTime", "isRange", "options.{timezone,format}")
  get toConfig() {
    let date = this.toDate;
    let time = this.toTime;
    const isRange = this.isRange;
    const options = this.options || {};
    const timeInferred = time ? false : true;

    if (time && !date) {
      date = moment().format(this.dateFormat);
    }

    let dateTime;
    if (!timeInferred) {
      dateTime = moment.tz(`${date} ${time}`, options.timezone);
    } else {
      dateTime = moment.tz(date, options.timezone).endOf("day");
    }

    if (!timeInferred) {
      time = dateTime.format(this.timeFormat);
    }

    let format = options.format;
    if (timeInferred && (format === "LLL" || format === "LLLL")) {
      format = "LL";
    }

    return EmberObject.create({
      date: dateTime.format(this.dateFormat),
      time,
      dateTime,
      format,
      range: isRange ? "end" : false,
    });
  }

  @computed(
    "recurring",
    "timezones",
    "timezone",
    "format",
    "countdown",
    "displayedTimezone"
  )
  get options() {
    return EmberObject.create({
      recurring: this.recurring,
      timezones: this.timezones,
      timezone: this.timezone,
      format: this.format,
      // no UI of their own: carried through so editing a date keeps them
      countdown: this.countdown,
      displayedTimezone: this.displayedTimezone,
    });
  }

  @computed(
    "fromConfig.date",
    "toConfig.date",
    "options.{recurring,timezones,timezone,format}"
  )
  get computedConfig() {
    return EmberObject.create({
      from: this.fromConfig,
      to: this.toConfig,
      options: this.options,
    });
  }

  @computed
  get currentUserTimezone() {
    return this.currentUser.user_option.timezone || moment.tz.guess();
  }

  @computed
  get allTimezones() {
    return moment.tz.names();
  }

  @computed("currentUserTimezone")
  get formattedCurrentUserTimezone() {
    return this.currentUserTimezone
      .replace("_", " ")
      .replace("Etc/", "")
      .replace("/", ", ");
  }

  @computed("formats")
  get previewedFormats() {
    return this.formats.map((format) => {
      return {
        format,
        preview: moment().format(format),
      };
    });
  }

  @computed
  get recurringOptions() {
    const key = "discourse_local_dates.create.form.recurring";

    return [
      {
        name: i18n(`${key}.every_day`),
        id: "1.days",
      },
      {
        name: i18n(`${key}.every_week`),
        id: "1.weeks",
      },
      {
        name: i18n(`${key}.every_two_weeks`),
        id: "2.weeks",
      },
      {
        name: i18n(`${key}.every_month`),
        id: "1.months",
      },
      {
        name: i18n(`${key}.every_two_months`),
        id: "2.months",
      },
      {
        name: i18n(`${key}.every_three_months`),
        id: "3.months",
      },
      {
        name: i18n(`${key}.every_six_months`),
        id: "6.months",
      },
      {
        name: i18n(`${key}.every_year`),
        id: "1.years",
      },
    ];
  }

  @computed("computedConfig.{from,to,options}", "options", "isValid", "isRange")
  get markup() {
    let text;

    if (this.isValid && this.computedConfig?.from) {
      if (this.computedConfig?.to && this.computedConfig?.to.range) {
        text = this._generateDateMarkup(
          this.computedConfig?.from,
          this.options,
          this.isRange,
          this.computedConfig?.to
        );
      } else {
        text = this._generateDateMarkup(
          this.computedConfig?.from,
          this.options,
          this.isRange
        );
      }
    }
    return text;
  }

  @computed("fromConfig.dateTime")
  get formattedFrom() {
    return this.fromConfig?.dateTime?.format("LLLL");
  }

  @computed("toConfig.dateTime")
  get formattedTo() {
    return this.toConfig?.dateTime?.isValid()
      ? this.toConfig?.dateTime?.format("LLLL")
      : i18n("discourse_local_dates.create.form.until");
  }

  @computed("fromSelected", "toSelected")
  get selectedDate() {
    return this.fromSelected ? this.date : this.toDate;
  }

  @computed("fromSelected", "toSelected")
  get selectedTime() {
    return this.fromSelected ? this.time : this.toTime;
  }

  didInsertElement() {
    super.didInsertElement(...arguments);
    this.send("focusFrom");
  }

  @observes("computedConfig.{from,to,options}", "options", "isValid", "isRange")
  configChanged() {
    this._renderPreview();
  }

  @action
  updateFormat(format, event) {
    event?.preventDefault();
    this.set("format", format);
  }

  @action
  changeSelectedDate(date) {
    if (this.fromSelected) {
      this.set("date", date);
    } else {
      this.set("toDate", date);
    }
  }

  @action
  changeSelectedTime(time) {
    if (this.fromSelected) {
      this.set("time", time);
    } else {
      this.set("toTime", time);
    }
  }

  @action
  eraseToDateTime() {
    this.setProperties({
      toDate: null,
      toTime: null,
    });
    this.focusFrom();
  }

  @action
  focusFrom() {
    this.setProperties({
      fromSelected: true,
      toSelected: false,
      minDate: null,
    });
  }

  @action
  focusTo() {
    this.setProperties({
      toSelected: true,
      fromSelected: false,
      minDate: this.get("fromConfig.date"),
    });
  }

  @action
  toggleAdvancedMode() {
    this.toggleProperty("advancedMode");
  }

  @action
  save() {
    const markup = this.markup;

    if (markup) {
      this.closeModal();
      this.model.insertDate(markup);
    }
  }

  @action
  cancel() {
    this.closeModal();
  }

  @debounce(INPUT_DELAY)
  async _renderPreview() {
    if (this.markup) {
      const result = await cook(this.markup);
      this.set("currentPreview", result);

      schedule("afterRender", () => {
        applyLocalDates(
          document.querySelectorAll(".preview .discourse-local-date"),
          this.siteSettings
        );
      });
    }
  }

  _generateDateMarkup(fromDateTime, options, isRange, toDateTime) {
    return generateDateMarkup(fromDateTime, options, isRange, toDateTime);
  }

  <template>
    <DModal
      class="discourse-local-dates-create-modal --large"
      @closeModal={{@closeModal}}
      @title={{if
        this.isEditing
        (i18n "discourse_local_dates.edit")
        (i18n "discourse_local_dates.title")
      }}
    >
      <:body>
        <div class="form">
          {{#if this.isValid}}
            {{#if this.timezoneIsDifferentFromUserTimezone}}
              <div class="preview alert alert-info">
                {{i18n "discourse_local_dates.create.form.current_timezone"}}
                <b
                >{{this.formattedCurrentUserTimezone}}</b>{{this.currentPreview}}
              </div>
            {{/if}}
          {{else}}
            <div class="validation-error alert alert-error">
              {{i18n "discourse_local_dates.create.form.invalid_date"}}
            </div>
          {{/if}}

          {{this.computeDate}}

          <div class="date-time-configuration">
            <div class="inputs-panel">
              <div
                class="date-time-control from
                  {{if this.fromSelected 'is-selected'}}
                  {{if this.fromFilled 'is-filled'}}"
              >
                {{dIcon "calendar-days"}}
                <DButton
                  autofocus
                  class="date-time"
                  id="from-date-time"
                  @action={{this.focusFrom}}
                  @translatedLabel={{this.formattedFrom}}
                />
              </div>

              <div
                class="date-time-control to
                  {{if this.toSelected 'is-selected'}}
                  {{if this.toFilled 'is-filled'}}"
              >
                {{dIcon "calendar-days"}}
                <DButton
                  class="date-time"
                  @action={{this.focusTo}}
                  @translatedLabel={{this.formattedTo}}
                />
                {{#if this.toFilled}}
                  <DButton
                    class="delete-to-date"
                    @action={{this.eraseToDateTime}}
                    @icon="xmark"
                  />
                {{/if}}
              </div>

              {{#if this.site.desktopView}}
                <TimezoneInput
                  @onChange={{fn (mut this.timezone)}}
                  @options={{hash icon="globe"}}
                  @value={{this.timezone}}
                />
              {{/if}}
            </div>

            <div class="picker-panel">
              <DCalendarDateTimeInput
                @date={{this.selectedDate}}
                @dateFormat={{this.dateFormat}}
                @datePickerId="local-date-create-form"
                @minDate={{this.minDate}}
                @onChangeDate={{this.changeSelectedDate}}
                @onChangeTime={{this.changeSelectedTime}}
                @time={{this.selectedTime}}
                @timeFormat={{this.timeFormat}}
              />
            </div>

            {{#if this.site.mobileView}}
              <TimezoneInput
                @onChange={{fn (mut this.timezone)}}
                @options={{hash icon="globe"}}
                @value={{this.timezone}}
              />
            {{/if}}
          </div>

          {{#if this.advancedMode}}
            <div class="advanced-options">
              {{#unless this.isRange}}
                <div class="control-group recurrence">
                  <label class="control-label">
                    {{i18n "discourse_local_dates.create.form.recurring_title"}}
                  </label>
                  <p>{{trustHTML
                      (i18n
                        "discourse_local_dates.create.form.recurring_description"
                      )
                    }}</p>
                  <div class="controls">
                    <ComboBox
                      class="recurrence-input"
                      @content={{this.recurringOptions}}
                      @onChange={{fn (mut this.recurring)}}
                      @options={{hash
                        none="discourse_local_dates.create.form.recurring_none"
                      }}
                      @value={{this.recurring}}
                    />
                  </div>
                </div>
              {{/unless}}

              <div class="control-group timezones">
                <label>{{i18n
                    "discourse_local_dates.create.form.timezones_title"
                  }}</label>
                <p>{{i18n
                    "discourse_local_dates.create.form.timezones_description"
                  }}</p>
                <div class="controls">
                  <MultiSelect
                    class="timezones-input"
                    @content={{this.allTimezones}}
                    @nameProperty={{null}}
                    @options={{hash allowAny=false maximum=5}}
                    @value={{this.timezones}}
                    @valueProperty={{null}}
                  />
                </div>
              </div>

              <div class="control-group format">
                <label>{{i18n
                    "discourse_local_dates.create.form.format_title"
                  }}</label>
                <p>
                  {{i18n
                    "discourse_local_dates.create.form.format_description"
                  }}
                  <a
                    href="https://momentjs.com/docs/#/parsing/string-format/"
                    rel="noopener noreferrer"
                    target="_blank"
                  >
                    {{dIcon "circle-question"}}
                  </a>
                </p>
                <div class="controls">
                  <DTextField class="format-input" @value={{this.format}} />
                </div>
              </div>
              <div class="control-group">
                <ul class="formats">
                  {{#each this.previewedFormats as |previewedFormat|}}
                    <li class="format">
                      <a
                        class="moment-format"
                        href
                        {{on
                          "click"
                          (fn this.updateFormat previewedFormat.format)
                        }}
                      >
                        {{previewedFormat.format}}
                      </a>
                      <span class="previewed-format">
                        {{previewedFormat.preview}}
                      </span>
                    </li>
                  {{/each}}
                </ul>
              </div>
            </div>
          {{/if}}
        </div>
      </:body>

      <:footer>

        {{#if this.isValid}}
          <DButton
            class="btn-primary"
            @action={{this.save}}
            @label={{if
              this.isEditing
              "discourse_local_dates.create.form.save"
              "discourse_local_dates.create.form.insert"
            }}
          />
        {{/if}}

        <DButton
          class="btn-flat"
          @action={{this.cancel}}
          @translatedLabel={{i18n "cancel"}}
        />

        <AdvancedModeToggle
          @active={{this.advancedMode}}
          @onToggle={{this.toggleAdvancedMode}}
        />
      </:footer>
    </DModal>
  </template>
}
import { withPluginApi } from "discourse/lib/plugin-api";

const PLUGIN_ID = "discourse-local-dates";

export default {
  name: "local-dates-admin-plugin-configuration-nav",

  initialize(container) {
    const currentUser = container.lookup("service:current-user");
    if (!currentUser?.admin) {
      return;
    }

    withPluginApi((api) => {
      api.setAdminPluginIcon(PLUGIN_ID, "far-clock");
    });
  },
};
import generateDateMarkup from "./local-date-markup-generator.js";

/**
 * Generates BBCode markup for the current date/time.
 * @param {string} [userTimezone] - User's timezone (defaults to browser guess)
 * @returns {string} BBCode markup
 */
export default function generateCurrentDateMarkup(userTimezone) {
  return generateDateMarkup(
    {
      date: moment().format("YYYY-MM-DD"),
      time: moment().format("HH:mm:ss"),
    },
    { timezone: userTimezone || moment.tz.guess() },
    false
  );
}
import { getProperties } from "@ember/object";

/*
  DateWithZoneHelper provides a limited list of helpers
  to manipulate a moment object with timezones

  - add(count unit) adds a COUNT of UNITS to a date
  - subtract(count unit) subtracts a COUNT of UNITS to a date
  - format(format) formats a date with zone in a consistent way, optional moment format
  - isDST() allows to know if a date in a specified timezone is currently under DST
  - datetimeWithZone(timezone) returns a new moment object with timezone applied
  - datetime returns the moment object
  - unitRepetitionsBetweenDates(duration, date) return the number of repetitions of
  duration between two dates, eg for duration: "1.weeks", "2.months"...
*/
export default class DateWithZoneHelper {
  static fromDatetime(datetime, timezone, localTimezone) {
    return new DateWithZoneHelper({
      year: datetime.year(),
      month: datetime.month(),
      day: datetime.date(),
      hour: datetime.hour(),
      minute: datetime.minute(),
      second: datetime.second(),
      timezone,
      localTimezone,
    });
  }

  constructor(params = {}) {
    this.timezone = params.timezone || "UTC";
    this.localTimezone = params.localTimezone || moment.tz.guess();

    this.datetime = moment.tz(
      getProperties(params, [
        "year",
        "month",
        "day",
        "hour",
        "minute",
        "second",
      ]),
      this.timezone
    );
  }

  isDST() {
    return this.datetime.tz(this.localTimezone).isDST();
  }

  unitRepetitionsBetweenDates(duration, date) {
    const [count, unit] = duration.split(".");
    // get the diff in the specified units with decimals
    const diff = Math.abs(this.datetime.diff(date, unit, true));
    // get integer count of duration in diff, eg: 4 hours diff is 2 for 2.hours duration
    const integer = Math.trunc(diff / count);
    // get fractional to define if we have to add one "duration"
    const fractional = (diff / count) % 1;

    return (
      integer * parseInt(count, 10) + (fractional > 0 ? parseInt(count, 10) : 0)
    );
  }

  add(count, unit) {
    return this._fromDatetime(
      this.datetime.clone().add(count, unit),
      this.timezone,
      this.localTimezone
    );
  }

  subtract(count, unit) {
    return this._fromDatetime(
      this.datetime.clone().subtract(count, unit),
      this.timezone,
      this.localTimezone
    );
  }

  datetimeWithZone(timezone) {
    return this.datetime.clone().tz(timezone);
  }

  format(format) {
    if (format) {
      return this.datetime.tz(this.localTimezone).format(format);
    }

    return this.datetime.tz(this.localTimezone).toISOString(true);
  }

  _fromDatetime(datetime, timezone, localTimezone) {
    return DateWithZoneHelper.fromDatetime(datetime, timezone, localTimezone);
  }
}
import { uniqueItemsFromArray } from "discourse/lib/array-tools";
import { renderIcon } from "discourse/lib/icon-library";
import { i18n } from "discourse-i18n";
import DateWithZoneHelper from "./date-with-zone-helper.js";

const DATETIME_FORMAT = "LLL";
const DATE_FORMAT = "LL";
const FULL_DATETIME_FORMAT = "LLLL";
const TIME_FORMAT = "h:mm A";
const DAY_OF_THE_WEEK_FORMAT = "dddd";
const RANGE_SEPARATOR = "→";
const TIME_ICON = "clock";
const SHORT_FORMAT_DAYS_PERIOD = 1;

export default class LocalDateBuilder {
  constructor(params = {}, localTimezone) {
    this.time = params.time;
    this.date = params.date;
    this.recurring = params.recurring;
    this.sameLocalDayAsFrom = params.sameLocalDayAsFrom;
    this.timezones = Array.from(
      new Set((params.timezones || []).filter(Boolean))
    );
    this.timezone = params.timezone || "UTC";
    this.calendar =
      typeof params.calendar === "undefined" ? true : params.calendar;
    this.displayedTimezone = params.displayedTimezone;
    this.format = params.format || (this.time ? DATETIME_FORMAT : DATE_FORMAT);
    this.countdown = params.countdown;
    this.duration = params.duration;
    this.localTimezone = localTimezone;
  }

  build() {
    const [year, month, day] = this.date.split("-").map((x) => parseInt(x, 10));
    const [hour, minute, second] = (this.time || "")
      .split(":")
      .map((x) => (x ? parseInt(x, 10) : undefined));

    let displayedTimezone;
    if (this.time) {
      displayedTimezone = this.displayedTimezone || this.localTimezone;
    } else {
      displayedTimezone =
        this.displayedTimezone || this.timezone || this.localTimezone;
    }

    let localDate = new DateWithZoneHelper({
      year,
      month: month ? month - 1 : null,
      day,
      hour,
      minute,
      second,
      timezone: this.timezone,
      localTimezone: this.localTimezone,
    });

    if (this.recurring && moment().isAfter(localDate.datetime)) {
      const type = this.recurring.split(".")[1];

      const repetitionsForType = localDate.unitRepetitionsBetweenDates(
        this.recurring,
        moment.tz(this.localTimezone)
